Here is the commit message:
apparmor: fix differential encoding verification

Differential encoding allows loops to be created if it is abused. To
prevent this the unpack should verify that a diff-encode chain
terminates.

Unfortunately the differential encode verification had two bugs.

1. it conflated states that had gone through check and already been
   marked, with states that were currently being checked and marked.
   This means that loops in the current chain being verified are treated
   as a chain that has already been verified.

2. the order bailout on already checked states compared current chain
   check iterators j,k instead of using the outer loop iterator i.
   Meaning a step backwards in states in the current chain verification
   was being mistaken for moving to an already verified state.

Move to a double mark scheme where already verified states get a
different mark, than the current chain being kept. This enables us
to also drop the backwards verification check that was the cause of
the second error as any already verified state is already marked.

Fixes: 031dcc8f4e84 ("apparmor: dfa add support for state differential encoding")
Reported-by: Qualys Security Advisory <qsa@qualys.com>
Tested-by: Salvatore Bonaccorso <carnil@debian.org>
Reviewed-by: Georgia Garcia <georgia.garcia@canonical.com>
Reviewed-by: Cengiz Can <cengiz.can@canonical.com>
Signed-off-by: John Johansen <john.johansen@canonical.com>

Here is the root cause:
The verify_dfa function used a single mark (MARK_DIFF_ENCODE) both for states in the current chain being checked and for states that had already been fully verified, causing loops in the current chain to be mistaken for already-verified chains. Additionally, the backward check (if k < j) incorrectly used inner loop variables instead of the outer loop index i, allowing jumps to earlier states within the same chain to be considered safe.

Here is the patch:
  */
 static int verify_dfa(struct aa_dfa *dfa)
 {
 	size_t i, state_count, trans_count;
 	int error = -EPROTO;

 	state_count = dfa->tables[YYTD_ID_BASE]->td_lolen;
 	trans_count = dfa->tables[YYTD_ID_NXT]->td_lolen;
 	if (state_count == 0)
 		goto out;
 	for (i = 0; i < state_count; i++) {
 		if (DEFAULT_TABLE(dfa)[i] >= state_count) {
 			pr_err("AppArmor DFA default state out of bounds");
 			goto out;
 		}
 		if (BASE_TABLE(dfa)[i] & MATCH_FLAGS_INVALID) {
 			pr_err("AppArmor DFA state with invalid match flags");
 			goto out;
 		}
 		if ((BASE_TABLE(dfa)[i] & MATCH_FLAG_DIFF_ENCODE)) {
 			if (!(dfa->flags & YYTH_FLAG_DIFF_ENCODE)) {
 				pr_err("AppArmor DFA diff encoded transition state without header flag");
 				goto out;
 			}
 		}
 		if ((BASE_TABLE(dfa)[i] & MATCH_FLAG_OOB_TRANSITION)) {
 			if (base_idx(BASE_TABLE(dfa)[i]) < dfa->max_oob) {
 				pr_err("AppArmor DFA out of bad transition out of range");
 				goto out;
 			}
 			if (!(dfa->flags & YYTH_FLAG_OOB_TRANS)) {
 				pr_err("AppArmor DFA out of bad transition state without header flag");
 				goto out;
 			}
 		}
 		if (base_idx(BASE_TABLE(dfa)[i]) + 255 >= trans_count) {
 			pr_err("AppArmor DFA next/check upper bounds error\n");
 			goto out;
 		}
 	}

 	for (i = 0; i < trans_count; i++) {
 		if (NEXT_TABLE(dfa)[i] >= state_count)
 			goto out;
 		if (CHECK_TABLE(dfa)[i] >= state_count)
 			goto out;
 	}

 	/* Now that all the other tables are verified, verify diffencoding */
 	for (i = 0; i < state_count; i++) {
 		size_t j, k;

 		for (j = i;
-		     (BASE_TABLE(dfa)[j] & MATCH_FLAG_DIFF_ENCODE) &&
-		     !(BASE_TABLE(dfa)[j] & MARK_DIFF_ENCODE);
+		     ((BASE_TABLE(dfa)[j] & MATCH_FLAG_DIFF_ENCODE) &&
+		      !(BASE_TABLE(dfa)[j] & MARK_DIFF_ENCODE_VERIFIED));
 		     j = k) {
+			if (BASE_TABLE(dfa)[j] & MARK_DIFF_ENCODE)
+				/* loop in current chain */
+				goto out;
 			k = DEFAULT_TABLE(dfa)[j];
 			if (j == k)
+				/* self loop */
 				goto out;
-			if (k < j)
-				break;		/* already verified */
 			BASE_TABLE(dfa)[j] |= MARK_DIFF_ENCODE;
 		}
+		/* move mark to verified */
+		for (j = i;
+		     (BASE_TABLE(dfa)[j] & MATCH_FLAG_DIFF_ENCODE);
+		     j = k) {
+			k = DEFAULT_TABLE(dfa)[j];
+			if (j < i)
+				/* jumps to state/chain that has been
+				 * verified
+				 */
+				break;
+			BASE_TABLE(dfa)[j] &= ~MARK_DIFF_ENCODE;
+			BASE_TABLE(dfa)[j] |= MARK_DIFF_ENCODE_VERIFIED;
+		}
 	}
 	error = 0;

 out:
 	return error;
 }



